import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Favicon, tarayıcı sekmesinde sayfa başlığının yanında görünen küçük simgedir. Genellikle bir ziyaretçinin fark ettiği ilk görsel ayrıntıdır ve sitene yer imlerinde, geçmişte ve cep telefonunun ana ekranında eşlik eder.</p>\n<p>Neredeyse kimse faviconları bilinçli olarak düşünmez ama eksik ya da bulanık olduğunda site eksik hissettirir. Keskin bir simge, içeriğinin tek bir kelimesini okumadan önce özen ve profesyonellik iletir.</p>\n<p>Bu kılavuzda bir favicon oluşturucunun ne yaptığını, tam bir simge paketinin hangi dosyaları içerdiğini ve logonu CompressMyPic ücretsiz aracıyla bitmiş bir pakete nasıl dönüştüreceğini açıklıyoruz. Her şey tarayıcında olur; hesap oluşturmadan ve hiçbir şeyi sunucuya yüklemeden.</p>\n<h2 id=\"what-is-a-favicon\">Favicon nedir?</h2>\n<p>Favicon, bir web sitesini tarayıcı içinde temsil eden küçük bir görüntü dosyasıdır. Sekme çubuğunda, yer imleri listesinde, geçmiş sayfasında ve bazı tarayıcılarda arama sonuçlarının yanında görünür.</p>\n<p>Adı İngilizce \"favorite icon\" (favori simge) ifadesinden gelir, çünkü ilk tarayıcılar onu kaydedilmiş sayfaların yanında gösterirdi.</p>\n<p>Klasik dosya favicon.ico'dur; tek dosyada birkaç simge boyutu saklayabilen özel bir kapsayıcı biçimidir. Modern tarayıcılar PNG simgeleri de kabul eder ve Apple ile Android cihazlar kendi daha büyük simge dosyalarını kullanır. Bu yüzden tam bir kurulum tek görüntü değil, birkaç dosya içerir.</p>\n<p>16'ya 16 pikselde favicon miniktir. Bu boyut her tasarım kararını belirler. İnce ayrıntılar kaybolur, ince çizgiler yitip gider ve küçük metin okunaksız olur. İyi bir favicon, pirinç tanesi boyutuna küçültüldüğünde bile ayakta kalan sade ve güçlü bir markadır.</p>\n<p>Birçok site favicon olarak logosunun basitleştirilmiş bir sürümünü kullanır. Uzun adlı bir logo tek harfe ya da kompakt bir sembole dönüşür. Ayrıntılı bir çizim yüksek kontrastlı düz bir biçime dönüşür. Amaç tanınmak, süslemek değildir.</p>\n<h2 id=\"why-every-website-needs-a-favicon\">Her web sitesinin favicon'a ihtiyacı neden vardır?</h2>\n<p>Favicon'u olmayan bir site sekmede genel bir küre ya da boş belge simgesi gösterir. Birçok sekmeyi açık tutanlar simgelerle gezinir ve boş bir sekmeyi yeniden bulmak daha zordur. Siten dolu bir sekme çubuğunda görünmez olur.</p>\n<p>Faviconlar yer imlerinde ve tarayıcı geçmişinde de görünür. Biri sayfanı kaydedip günler sonra döndüğünde simge, siteni onlarca kaydedilmiş bağlantı arasında tanımlayan görsel ipucudur. Tanınabilir bir simge insanların dönmesini sağlar.</p>\n<p>Cep telefonunda favicon, biri siteni ana ekrana eklediğinde kullanılan simgeyi besler. Apple cihazlar Apple Touch Icon'u, Android cihazlar web manifestosundaki simgeleri kullanır. Bu dosyalar olmadan kısayol çirkin bir ekran görüntüsü ya da genel bir harf alır.</p>\n<p>Arama motorları bazen favicon'u sayfalarının yanında sonuçlarda gösterir. Kurulduktan sonra hiçbir şeye mal olmayan küçük bir marka yüzeyidir. Eksikliği bir sıralama cezası değildir ama varken sonucun ayırt edilmesi daha kolay olur.</p>\n<h2 id=\"what-the-favicon-generator-creates\">Favicon oluşturucu ne oluşturur?</h2>\n<p><a href=\"/tr/favicon-olusturucu\">Favicon oluşturucu</a>, yüklediğin bir logo ya da grafiği tam bir simge paketine dönüştürür. Çok boyutlu bir favicon.ico dosyası, Apple Touch simgeleri, 192'ye 192 ve 512'ye 512 piksel Android Chrome simgeleri, bir site.webmanifest dosyası ve yapıştırmaya hazır bir HTML parçası oluşturur.</p>\n<p>Her şey tek bir ZIP indirmesinde paketlenir; bu yüzden tüm dosyaları bir kerede alırsın. Yalnızca birine ihtiyacın varsa favicon.ico ya da apple-touch-icon.png gibi tek dosyaları da indirebilirsin. Filigran yok, hesap yok ve ücret yok.</p>\n<p>Ürettiği favicon.ico dosyası, yeniden adlandırılmış bir PNG değil, gerçek çok kareli ikili bir ICO dosyasıdır. Bu önemlidir, çünkü eski tarayıcılar ve bazı araçlar gerçek bir ICO kapsayıcısı bekler. Dosyanın içinde birkaç boyut vardır; bu yüzden tarayıcı her bağlam için en keskin olanı seçer.</p>\n<p>Oluşturucu tamamen tarayıcında çalışır. Logon cihazından asla çıkmaz; bu görüntü yayımlanmamış bir marka ya da ambargo altındaki bir müşteri logosu olduğunda önemlidir. Yüklenecek ya da sunucuda saklanacak hiçbir şey yoktur.</p>\n<h2 id=\"choosing-a-source-image\">Kaynak görüntü nasıl seçilir?</h2>\n<p>PNG ya da SVG biçiminde kare bir logo en keskin sonuçları verir. SVG idealdir, çünkü her boyuta kenarları kaybetmeden ölçeklenir; yüksek çözünürlüklü bir PNG ise büyük başladığı sürece iyi çalışır. Araç 20 MB'a kadar PNG, SVG, JPG, WebP ve HEIC dosyalarını kabul eder.</p>\n<p>Bulabildiğin logonun en büyük sürümüyle başla. 1024'e 1024 piksellik bir görüntü 16 piksele sorunsuz küçülürken, 64 piksellik bir görüntü yukarı gerildiğinde yumuşak ve bulanık görünür. Büyük görüntüler oluşturucuya her boyutta çalışacak daha fazla piksel verir.</p>\n<p>Şeffaf arka planlı logolar sekmelerde genellikle daha iyi görünür, çünkü sekmenin rengi markanın etrafından görünür. Katı bir arka plan da işe yarayabilir; özellikle uygulama simgelerinde. Ama şeffaflık simgeyi tarayıcının açık ve koyu temalarında esnek tutar.</p>\n<p>Logon dikdörtgense oluşturucu onu germeden kare tuvalin içine sığdırır. Bu oranları dürüst tutar ama yanlarda boş alan bırakabilir. Markanın kare bir sürümü ya da kırpılmış bir ayrıntı genellikle minik tuvali daha iyi doldurur.</p>\n<h2 id=\"padding-corner-radius-and-background-fill\">Dolgu, köşe yarıçapı ve arka plan rengi</h2>\n<p>Dolgu, logon ile simge tuvalinin kenarı arasındaki havayı kontrol eder. Kenarlara dokunan bir logo 16 pikselde sıkışık görünür; bu yüzden biraz dolgu markayı okunaklı tutar. Çok fazla dolgu logoyu nokta hâline gelene kadar küçültür; bu yüzden denge önemlidir.</p>\n<p>Köşe yarıçapı simge arka planının köşelerini yuvarlar. Küçük bir yarıçap biçimi yumuşatırken, büyük bir yarıçap simgeyi daireye dönüştürür. Yuvarlak simgeler uygulama tarzı markalarla iyi giderken, kare simgeler resmi ya da teknik markalarla iyi gider.</p>\n<p>Arka plan rengi şeffaf bir logonun arkasında ne olduğunu belirler. Katı bir dolgu simgeyi her sekme renginde öne çıkarır; bu logo ince ya da soluk olduğunda yararlıdır. Şeffaf bir dolgu simgeyi hafif tutar ve tarayıcının temasını gösterir.</p>\n<p>Bu üç kontrol paketteki tüm boyutları aynı anda günceller. Dolguyu bir kez değiştir; 16 piksellik sekme simgesi, 180 piksellik Apple simgesi ve 512 piksellik Android simgesi değişimi izler. Bu tutarlılık paketi birçok ayrı dosya değil, tek tasarım gibi hissettirir.</p>\n<h2 id=\"light-and-dark-tab-previews\">Açık ve koyu sekme önizlemeleri</h2>\n<p>Oluşturucu simgeni açık ve koyu sekme arka planları üzerinde gösterir. Bu önizleme önemlidir, çünkü koyu bir logo koyu bir sekmede kaybolur ve açık bir logo açık bir sekmede yitip gider. Birçok favicon bir temada iyi görünür ve diğerinde görünmez olur.</p>\n<p>İndirmeden önce iki önizlemeyi de incele. Logon koyuysa koyu modda ayakta kalması için açık bir arka plan dolgusu ya da soluk bir kontur ekle. Logon açıksa koyu bir dolgu ya da daha güçlü bir renk onu açık sekmelerde görünür tutar.</p>\n<p>Bazı tasarımcılar tam da bu sorunu çözmek için markanın arkasına ince bir arka plan biçimi ekler. Marka rengiyle doldurulmuş yuvarlak köşeli bir kare simgeye her temada tutarlı bir arka plan verir ve ayrıca tanınabilir bir uygulama simgesi biçimi olarak işe yarar.</p>\n<p>Önizleme süs değildir. Faviconların en yaygın arızasını yakalar: tasarım aracında mükemmel görünen ama gerçek bir tarayıcıda kaybolan bir simge. Otuz saniyelik bir inceleme sana tüm paketi yeniden yükleme turunu kazandırır.</p>\n<h2 id=\"the-html-snippet-and-file-placement\">HTML parçası ve dosyaların yerleşimi</h2>\n<p>Paketi oluşturduktan sonra dosyaları web sitene yüklersin ve sayfalarının head bölümüne kısa bir HTML parçası eklersin. Parça tarayıcıya her simgenin nerede yaşadığını söyler; Apple Touch Icon ve web manifestosu dahil. Oluşturucu bu parçayı yapıştırmaya hazır teslim eder.</p>\n<p>Dosyaların olağan yeri web sitenin kök klasörüdür; ana sayfanın bulunduğu klasör. Tarayıcılar varsayılan olarak kökte favicon.ico arar; bu yüzden onu oraya koymak parçayı unutan sayfaları bile kapsar. Diğer dosyalar da aynı klasöre gider; parçan başka bir yeri göstermedikçe.</p>\n<p>Parça sade HTML siteleriyle ve React ile Next.js gibi çerçevelerle çalışır. Bir çerçevede head bölümü her sayfada değil, şablon ya da tasarım dosyasında yaşar. Bağlantıları o paylaşılan dosyaya bir kez ekle; tüm sayfalar onları miras alır.</p>\n<p>Dosya adlarını oluşturulduğu gibi tam olarak koru. Parçayı güncellemeden bir dosyanın adını değiştirirsen bağlantı bozulur ve tarayıcı varsayılan simgeye döner. Dosyaları bir alt klasöre taşırsan parçadaki her yolu güncelle.</p>\n<h2 id=\"apple-touch-icons-and-android-icons\">Apple Touch simgeleri ve Android simgeleri</h2>\n<p>Apple cihazlar, bir ziyaretçi siteni ana ekrana eklediğinde 180'e 180 piksellik bir Apple Touch Icon kullanır. Apple bu simgede şeffaflığı yok sayar ve şeffaf bölgeleri siyahla doldurur; bu yüzden katı bir arka plan şeffaf olandan daha iyi çalışır.</p>\n<p>Marka renginde bir kare üzerindeki logo güvenli seçimdir.</p>\n<p>Android cihazlar web manifestosundaki simgeleri okur: ana ekran için 192'ye 192 ve karşılama ekranı ile yükleme istemi için 512'ye 512. İki boyut da pakette gelir; bu yüzden Android kullanıcıları her adımda keskin bir simge alır.</p>\n<p>Bu daha büyük simgeler önemlidir, çünkü sekme favicon'undan çok daha büyük gösterilirler. 16 pikselde iyi okunan bir marka 512'de boş görünebilir ve ayrıntılı bir logo büyükte çok iyi ama küçükte bulanık görünebilir. Oluşturucu aynı tasarımı her boyutta çizer; böylece iki ucu da değerlendirebilirsin.</p>\n<p>Paketi kurduktan sonra ana ekran simgesini gerçek bir telefonda dene. Siteyi ana ekrana ekle, simgeye diğer uygulamalarının yanında bak ve soluk ya da kırpılmış görünmediğini doğrula. Telefonda hızlı bir deneme, masaüstü önizlemesinin gösteremeyeceği sorunları yakalar.</p>\n<h2 id=\"the-site-webmanifest-file\">site.webmanifest dosyası</h2>\n<p>site.webmanifest dosyası, siteni kurulabilir bir web uygulaması olarak tanımlayan küçük bir JSON dosyasıdır. Sitenin adını, tema rengini ve boyutları ile amaçları olan simge dosyalarını listeler. Tarayıcılar onu ana ekran kısayolları ve yükleme istemleri oluşturmak için okur.</p>\n<p>Oluşturucu bu dosyayı senin için yazar; 192 ve 512 piksellik simgeler ve doğru boyut etiketleri dahil. JSON'u elle yazman ya da manifesto biçimini hatırlaman gerekmez. Dosyayı simgelerinle birlikte yükle ve HTML parçasında ona bağlan.</p>\n<p>Manifestodaki tema rengi, siten açıkken Android'de tarayıcı çubuğunu boyar. Markanla uyuşan bir renk seç; tarayıcı çubuğu tasarımınla kaynaşır. Sitenin cep telefonunda özenli hissettirmesini sağlayan küçük bir ayrıntıdır.</p>\n<p>Sonra sitenin adını ya da marka renklerini değiştirirsen manifestoyu güncelle ve paketi yeniden oluştur. Manifesto sade metindir; bu yüzden adı değiştirmek için küçük bir değişiklik yeter ama yeniden oluşturmak simgeleri ve manifestoyu senkron tutar.</p>\n<h2 id=\"common-favicon-mistakes\">Faviconlarla yaygın hatalar</h2>\n<p>En yaygın hata küçük metinli ayrıntılı bir logo yüklemektir. 16 pikselde bir slogan gri gürültüye dönüşür ve ince çizgili bir logo lekeye dönüşür. Önce markayı basitleştir, sonra paketi oluştur. Logo basitleştirilemiyorsa tek bir baş harf ya da onun bir sembolünü kullan.</p>\n<p>Bir başka hata düşük çözünürlüklü bir kaynak görüntü kullanmaktır. Android simgesi için 512'ye gerilmiş 32 piksellik bir görüntü yumuşak ve profesyonellikten uzak görünür. Her zaman sahip olduğun en büyük logo dosyasıyla başla; ideal olarak vektör SVG ya da en az 512 piksellik bir PNG.</p>\n<p>Üçüncü bir hata Apple Touch Icon'un arka planını unutmaktır. Bir iPhone ana ekranında şeffaf bir logo, oluşturma hatası gibi görünen siyah köşeler alır. Sekme favicon'u şeffaf kalsa bile Apple simgesine katı bir dolgu ver.</p>\n<p>Son olarak birçok site manifestoyu tamamen atlar ve sonra Android'in simge yerine neden ekran görüntüsü gösterdiğini merak eder. Manifesto Android'in okuduğu dosyadır; bu yüzden olmadan uygun bir ana ekran simgesi olmaz. Paketi yüklerken onu ekle.</p>\n<h2 id=\"updating-a-favicon-without-cache-trouble\">Önbellek sorunu olmadan favicon güncelleme</h2>\n<p>Tarayıcılar faviconları çok agresif önbelleğe alır; bazen haftalarca. Yeni bir paket yükledikten sonra kendi tarayıcın dosyalar değişmiş olsa bile eski simgeyi göstermeye devam edebilir. Bu normal önbellektir, bozuk bir yükleme değildir.</p>\n<p>En basit çözüm sayfayı zorla yenilemek ya da o site için tarayıcı önbelleğini temizlemektir. Chrome'da Ctrl, Shift ve R ile zorla yenileme genellikle yeni simgeyi zorlar. İşe yaramazsa favicon URL'sini doğrudan aç ve o sayfayı yenile.</p>\n<p>Ziyaretçiler için yeni simge, önbellekleri dolduğunda ya da yeni bir cihazdan ziyaret ettiklerinde görünür. Simge bağlantılarına favicon.ico sonuna sürüm numarası gibi bir sorgu ekleyerek süreci hızlandırabilirsin. Tarayıcı onu yeni bir dosya olarak ele alır ve hemen indirir.</p>\n<p>Marka değiştirirken tek bir dosya yerine tüm paketi yeniden oluştur. Kısmi bir güncelleme uyuşmayan boyutlar bırakır; sekmede yeni marka, ana ekranda eski marka olur. Tam bir yeniden oluşturma her boyutu tutarlı tutar.</p>\n<h2 id=\"quick-reference\">Hızlı başvuru: favicon paketi denetim listesi</h2>\n<p>En az 512 piksellik PNG ya da SVG biçiminde kare bir logoyla başla. Markanın nefes alması için dolguyu ayarla, açık ve koyu sekmelerde ayakta kalan bir arka plan rengi seç ve indirmeden önce iki önizlemeyi de incele.</p>\n<p>ZIP içeriğini sitenin köküne yükle, HTML parçasını paylaşılan head şablonuna yapıştır ve Android için manifestoyu ekle. Sonra sekme simgesini, yer imi simgesini ve gerçek bir telefondaki ana ekran simgesini dene.</p>\n<p>Tam adım adım için <a href=\"/tr/blog/favicon-nasil-olusturulur\">Favicon Nasıl Oluşturulur?</a> yazısını oku ve her boyutu açıklanmış görmek için <a href=\"/tr/blog/favicon-boyutlari-aciklandi\">Favicon Boyutları Açıklaması: 16×16'dan 512×512'ye</a> yazısını oku. Paketini şimdi oluşturmak için <a href=\"/tr/favicon-olusturucu\">favicon oluşturucu</a> aracını aç.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Favicon nedir?","answer":"Favicon, tarayıcı sekmelerinde, yer imlerinde, geçmişte ve ana ekran kısayollarında bir web sitesini temsil eden küçük bir simgedir. Klasik dosya favicon.ico'dur ama tam bir kurulum PNG simgeleri, Apple Touch Icon ve Android için web manifestosu da içerir."},{"question":"Sitem küçükse favicon'a ihtiyacım var mı?","answer":"Evet. Tek sayfalık bir site bile favicon'u yoksa sekmede genel ya da boş bir simge gösterir ve bu özensiz görünür. Favicon eklemek hiçbir şeye mal olmaz, ziyaretçilerin sekmeni yeniden bulmasına yardımcı olur ve yer imleri ile kısayolları tanınabilir yapar."},{"question":"Fotoğrafı favicon olarak kullanabilir miyim?","answer":"Kullanabilirsin ama fotoğraflar nadiren iyi çalışır. 16'ya 16 piksele küçültülmüş bir fotoğraf tanınmaz bir bulanıklığa dönüşür. Sade bir logo, sembol ya da iyi kontrastlı tek harf, favicon boyutunda her fotoğraftan çok daha iyi okunur."},{"question":"favicon.ico ile PNG favicon arasındaki fark nedir?","answer":"ICO biçimi, tek dosyada birkaç simge boyutu saklayabilen bir kapsayıcıdır ve tarayıcılar onu on yıllardır destekler. Bir PNG favicon tek boyut saklar; bu yüzden her boyut için ayrı dosyalara ihtiyaç duyar. Tam bir paket sekme için ICO'yu ve daha büyük bağlamlar için PNG dosyalarını kullanır."},{"question":"Favicon paketi oluşturmak ne kadar sürer?","answer":"Birkaç dakika. Logonu yükle, dolguyu, köşe yarıçapını ve arka plan rengini ayarla, açık ve koyu önizlemeleri incele ve ZIP'i indir. Dosyaları sitene kurmak, yükleme ve HTML parçasını yapıştırma ile birkaç dakika daha sürer."},{"question":"Favicon sitemin arama sonuçlarında sıralanmasına yardımcı olur mu?","answer":"Doğrudan değil. Favicon bir sıralama faktörü değildir ama bazı arama sonuçları onu bağlantının yanında gösterir; bu sonucunun görülmesini ve tıklanmasını kolaylaştırabilir. Gerçek değeri markada ve kullanılabilirliktedir, sıralamada değil."}];
